recipes.code:
{
  "inputs": [
    {
      "id": "webcake-jwt",
      "type": "promptString",
      "description": "Webcake backend JWT; required only for the persistence tools (create/update/list pages).",
      "password": true
    },
    {
      "id": "pexels-api-key",
      "type": "promptString",
      "description": "Optional Pexels API key for search_images; without one a shared hosted proxy is used.",
      "password": true
    }
  ],
  "servers": {
    "webcake-landing": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "webcake-landing-mcp@1.5.0"
      ],
      "env": {
        "WEBCAKE_JWT": "${input:webcake-jwt}",
        "WEBCAKE_ENV": "<webcake-env>",
        "WEBCAKE_API_BASE": "<webcake-api-base>",
        "WEBCAKE_ORG_ID": "<webcake-org-id>",
        "PEXELS_API_KEY": "${input:pexels-api-key}"
      }
    }
  }
}
